import test from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices } from '../src/reports.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices returns empty list for no invoices', () => {
  const result = overdueInvoices([], '2026-10-15');

  assert.equal(result.ok, true);
  assert.deepEqual(result.value, []);
});

test('overdueInvoices rejects invalid asOf date', () => {
  const result = overdueInvoices([], 'invalid');

  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('overdueInvoices rejects impossible asOf date', () => {
  const result = overdueInvoices([], '2026-02-30');

  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('overdueInvoices includes invoice with dueDate before asOf', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv1, []).value;
  // dueDate is 2026-10-19

  const result = overdueInvoices([issued], '2026-10-25');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].number, 'INV-2026-0001');
  assert.equal(result.value[0].daysOverdue, 6); // 2026-10-25 - 2026-10-19
});

test('overdueInvoices excludes invoice with dueDate on asOf', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv1, []).value;
  // dueDate is 2026-10-19

  const result = overdueInvoices([issued], '2026-10-19');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('overdueInvoices excludes invoice with dueDate after asOf', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv1, []).value;
  // dueDate is 2026-10-19

  const result = overdueInvoices([issued], '2026-10-15');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('overdueInvoices includes partially_paid invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv1, []).value;
  const paid = recordPayment(issued, { amount: 5000, date: '2026-10-20' }).value;

  const result = overdueInvoices([paid], '2026-10-25');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].due, 6495); // 11495 - 5000
});

test('overdueInvoices excludes draft invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const result = overdueInvoices([inv1], '2026-10-25');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
});

test('overdueInvoices excludes paid invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv1, []).value;
  const paid = recordPayment(issued, { amount: 11495, date: '2026-10-20' }).value;

  const result = overdueInvoices([paid], '2026-10-25');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 0);
  assert.equal(result.value[0]?.due, undefined);
});

test('overdueInvoices sorts by daysOverdue descending', () => {
  // Invoice 1: due 2026-10-10
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-26',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  // Invoice 2: due 2026-10-15
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued2 = issueInvoice(inv2, []).value;

  // Invoice 3: due 2026-10-12
  const inv3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-09-28',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued3 = issueInvoice(inv3, []).value;

  const result = overdueInvoices([issued1, issued2, issued3], '2026-10-25');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 3);
  // Most overdue first
  assert.equal(result.value[0].daysOverdue, 15); // due 2026-10-10, 15 days overdue
  assert.equal(result.value[1].daysOverdue, 13); // due 2026-10-12, 13 days overdue
  assert.equal(result.value[2].daysOverdue, 10); // due 2026-10-15, 10 days overdue
});

test('overdueInvoices returns correct fields', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv1, []).value;

  const result = overdueInvoices([issued], '2026-10-25');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].number, 'INV-2026-0001');
  assert.equal(result.value[0].customerId, 'C-002');
  assert.equal(result.value[0].dueDate, '2026-10-19');
  assert.equal(result.value[0].daysOverdue, 6);
  assert.equal(result.value[0].due, 11495);
});

test('overdueInvoices with multiple customers', () => {
  // Customer C-001
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  // Customer C-002
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued2 = issueInvoice(inv2, []).value;

  const result = overdueInvoices([issued1, issued2], '2026-10-25');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 2);
  assert.equal(result.value[0].customerId, 'C-002'); // More overdue
  assert.equal(result.value[1].customerId, 'C-001');
});

test('overdueInvoices with EOM payment terms', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'EOM',
  }).value;

  const issued = issueInvoice(inv1, []).value;
  // dueDate is 2026-10-31

  const result = overdueInvoices([issued], '2026-11-05');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].dueDate, '2026-10-31');
  assert.equal(result.value[0].daysOverdue, 5);
});

test('overdueInvoices with NET30 payment terms', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv1, []).value;
  // dueDate is 2026-11-04 (NET30 default)

  const result = overdueInvoices([issued], '2026-11-10');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].daysOverdue, 6);
});

test('overdueInvoices with large number of invoices', () => {
  const invoices = [];
  for (let i = 0; i < 10; i++) {
    const inv = createInvoice({
      customerId: 'C-002',
      issueDate: `2026-10-0${i % 9 + 1}`,
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
      terms: 'NET14',
    }).value;
    invoices.push(issueInvoice(inv, []).value);
  }

  const result = overdueInvoices(invoices, '2026-10-25');

  assert.equal(result.ok, true);
  assert(result.value.length > 0);
  // Verify sorted by daysOverdue descending
  for (let i = 0; i < result.value.length - 1; i++) {
    assert(result.value[i].daysOverdue >= result.value[i + 1].daysOverdue);
  }
});

test('overdueInvoices with partially paid invoices at different stages', () => {
  // Partially paid with some due
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
    terms: 'NET14',
  }).value;
  const issued1 = issueInvoice(inv1, []).value;
  const paid1 = recordPayment(issued1, { amount: 10000, date: '2026-10-10' }).value;

  const result = overdueInvoices([paid1], '2026-10-25');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  // Due should be remaining balance
  assert.equal(result.value[0].due, 12990); // 22990 - 10000
});

test('overdueInvoices handles undefined invoices in array', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;
  const issued1 = issueInvoice(inv1, []).value;

  const result = overdueInvoices([issued1, undefined, null], '2026-10-25');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
});

test('overdueInvoices with exactly one day overdue', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-18',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv1, []).value;
  // dueDate is 2026-11-01

  const result = overdueInvoices([issued], '2026-11-02');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].daysOverdue, 1);
});

test('overdueInvoices with many days overdue', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv1, []).value;
  // dueDate is 2026-01-15

  const result = overdueInvoices([issued], '2026-10-25');

  assert.equal(result.ok, true);
  assert.equal(result.value.length, 1);
  assert(result.value[0].daysOverdue > 250); // More than 250 days overdue
});

test('overdueInvoices returns empty array when none are overdue', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-20',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    terms: 'NET14',
  }).value;

  const issued = issueInvoice(inv1, []).value;
  // dueDate is 2026-11-03

  const result = overdueInvoices([issued], '2026-10-25');

  assert.equal(result.ok, true);
  assert.deepEqual(result.value, []);
});

